const read=(k,f)=>{try{let v=localStorage.getItem(k);return v?JSON.parse(v):f}catch{return f}},write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const n=v=>{if(v===null||v===undefined||v==='')return null;if(typeof v==='string'&&['nan','none','null','nat'].includes(v.trim().toLowerCase()))return null;let x=Number(v);return Number.isFinite(x)?x:null}, fmt=(v,d=1,s="")=>n(v)==null?"—":`${n(v).toFixed(d)}${s}`, signed=(v,d=2,s="")=>n(v)==null?"—":`${n(v)>0?"+":""}${n(v).toFixed(d)}${s}`;
