async function api(path,opt={}){let r=await fetch(path,{headers:{"Content-Type":"application/json",...(opt.headers||{})},...opt});if(!r.ok)throw new Error(`${r.status} ${await r.text()}`);return (r.headers.get("content-type")||"").includes("json")?r.json():r.text()}
let liveSocket=null,liveSocketCompany=null,liveSocketConnected=false,liveSocketTimer=null;
function desiredLiveCompany(){if(st.page==='market')return st.marketFocusId;if(['dashboard','company','history'].includes(st.page))return st.focusId;return null}
function wsFreshness(r){let q=String(r?.quality_state||'');if(q==='实时可比')return r?.stale_flag?'陈旧':'实时';return ({'单边指示':'单边','竞价指示':'竞价','午间快照':'午间','上一收盘':'上一收盘','收盘口径':'收盘','单边收盘参考':'收盘参考','手动快照':'手动','暂停计算':'暂停计算','等待行情':'本地缓存'}[q]||'本地缓存')}
function closeLiveSocket(){if(liveSocketTimer){clearTimeout(liveSocketTimer);liveSocketTimer=null}if(liveSocket){try{liveSocket.onclose=null;liveSocket.close()}catch{}}liveSocket=null;liveSocketCompany=null;liveSocketConnected=false}
function connectLiveSocket(id){id=String(id||'');if(!id){closeLiveSocket();return}if(liveSocket&&liveSocketCompany===id&&(liveSocket.readyState===0||liveSocket.readyState===1))return;closeLiveSocket();liveSocketCompany=id;api('/api/live/focus/'+encodeURIComponent(id),{method:'POST',body:'{}'}).catch(()=>{});let proto=location.protocol==='https:'?'wss':'ws';let ws=new WebSocket(`${proto}://${location.host}/ws/live/${encodeURIComponent(id)}`);liveSocket=ws;ws.onopen=()=>{if(liveSocket!==ws)return;liveSocketConnected=true;try{ws.send('ready')}catch{}};ws.onmessage=e=>{if(liveSocket!==ws)return;let d;try{d=JSON.parse(e.data)}catch{return}if(d.type!=='quote'||!d.row)return;let r=d.row,cid=String(d.company_id||id);if(d.market)st.market=d.market;if(st.marketRows?.length){let i=st.marketRows.findIndex(x=>String(x.company_id)===cid);if(i>=0){st.marketRows[i]={...st.marketRows[i],...r,freshness:wsFreshness(r)};if(st.marketFocusId===cid){st.marketFocus=st.marketRows[i];renderMarketFocus(false);renderMarketTable()}}}if(st.focusId===cid&&st.focus){st.focus={...st.focus,...r,a_close:r.a_price,h_close:r.h_price,display_premium_pct:r.premium_pct,display_change_pp:r.premium_change_pp,live_age_seconds:0,live_source:r.source};renderFocus()}if(st.page==='market'&&st.marketFocusId===cid){st.marketSummary.last_crawl=r.fetched_at||st.marketSummary.last_crawl;renderMarketStatus()}};ws.onerror=()=>{liveSocketConnected=false};ws.onclose=()=>{if(liveSocket!==ws)return;liveSocketConnected=false;liveSocket=null;let wanted=desiredLiveCompany();if(wanted===id&&st.settings?.autoRefresh!==false)liveSocketTimer=setTimeout(()=>connectLiveSocket(id),900)}}
function ensureLiveSocket(){let id=desiredLiveCompany();if(id)connectLiveSocket(id);else closeLiveSocket()}
function toast(t,d=""){let x=document.createElement("div");x.className="toast";x.innerHTML=`<b>${esc(t)}</b>${d?`<span>${esc(d)}</span>`:""}`;$("#toastStack").append(x);setTimeout(()=>x.remove(),3200)}
function modal(id,on=true){$(id).classList.toggle("open",on)} function drawer(id,on=true){$(id).classList.toggle("open",on)} function active(parent,b){$$('button',parent).forEach(x=>x.classList.toggle('active',x===b))}
function time(v){let d=v instanceof Date?v:new Date(v);return Number.isNaN(d.getTime())?String(v||"—"):d.toLocaleTimeString("zh-CN",{hour12:false})}
function dateOnly(v){if(v==null||v==='')return '—';let x=String(v);if(/^\d{4}-\d{2}-\d{2}/.test(x))return x.slice(0,10);let d=new Date(v);return Number.isNaN(d.getTime())?x.replace('T00:00:00','').replace(' 00:00:00',''):d.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}).replaceAll('/','-')}
function localCalendarDate(){let d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function renderCalendarDate(){let el=$('#analysisDate');if(el)el.textContent=localCalendarDate()}
function chartValue(v){if(n(v)==null)return '—';let a=Math.abs(n(v));return a>=1e8?(n(v)/1e8).toFixed(2)+'亿':a>=1e4?(n(v)/1e4).toFixed(1)+'万':n(v).toFixed(2)}

function updateSidebarToggle(){let btn=$('#sidebarToggle'),side=$('#sidebar');if(!btn||!side)return;let collapsed=side.classList.contains('collapsed');btn.textContent=collapsed?'›':'‹';btn.title=collapsed?'展开侧栏':'折叠侧栏'}
