async function init(){st.settings=read(STORE.settings,{autoRefresh:true,compact:true,showLive:true});st.visibleCols=read(STORE.columns,DEFAULT_COLS);st.priorityCols=read(STORE.priorityColumns,PRESETS[0].cols);st.screens=read(STORE.screens,{});st.watchViews=read(STORE.watchViews,{});st.alerts=read(STORE.alerts,{});st.layout=read(STORE.layout,'default');bind();applyLayout(st.layout,false);displaySettings();renderSavedScreens();renderCustomWatchViews();renderCalendarDate();await boot();await Promise.all([loadSummary(),loadWatch(),loadScreen(),loadSources()]);st.focusId=read(STORE.focus,null)||st.boot.focus_company_id;await loadFocus(true);await loadQuality();setInterval(autoTick,1000);setInterval(renderCalendarDate,60000)}
async function boot(){try{st.boot=await api('/api/bootstrap');st.market=st.boot.market;updateDataMode(st.boot);renderCalendarDate();$('#filterIndustry').innerHTML='<option>全部</option>'+(st.boot.industries||[]).map(x=>`<option>${esc(x)}</option>`).join('');marketUi()}catch(e){renderCalendarDate();toast('启动失败',e.message)}}
async function loadSummary(){try{st.summary=await api('/api/summary');st.market=st.summary.market||st.market;renderSummary();marketUi()}catch(e){toast('摘要刷新失败',e.message)}}
function renderSummary(){let s=st.summary||{};$('#sumUniverse').textContent=s.total??st.boot?.universe_log?.active_count??'—';$('#sumAnalyzable').textContent=s.analyzable??'—';$('#sumPriority').textContent=s.high_priority??'—';$('#sumWatchAlerts').textContent=s.watchlist_alerts??'—';$('#sumQuality').textContent=s.quality_issues??'—';$('#summaryNarrative').textContent=s.high_priority?`今日 ${s.high_priority} 家公司进入高优先级研究池。待核验样本不会进入正式排序。`:'当前未发现达到高优先级阈值的可分析样本。'}

async function loadScreen(){try{let f=st.filters,p=new URLSearchParams({search:f.search,industry:f.industry,quality:f.quality,research_state:f.research_state,min_change:String(f.min_change),min_priority:String(f.min_priority),sort_by:st.sort.by,sort_dir:st.sort.dir,limit:'500'});let d=await api('/api/screener?'+p);st.screenRows=d.rows||[];st.screenCount=d.count||0;renderScreen();renderPriority();renderNotifications()}catch(e){toast('扫描器刷新失败',e.message)}}
function col(row,k){if(k==='premium')return `<span class="${vclass(row.display_premium_pct)}">${fmt(row.display_premium_pct,1,'%')}</span>`;if(k==='change')return `<span class="${vclass(row.display_change_pp)}">${signed(row.display_change_pp,2,'pp')}</span>`;if(k==='percentile')return pct(row.premium_percentile);if(k==='driver')return esc(row.driver_label||row.driver_market||'—');if(k==='residual')return `<span class="${vclass(row.company_residual_pp)}">${signed(row.company_residual_pp,2,'pp')}</span>`;if(k==='quality')return `<span class="pill ${qclass(row.quality_state)}" title="${esc(row.quality_reason||'')}">${esc(row.quality_state||'—')}</span>`;if(k==='priority')return `<span class="pill ${rclass(row.research_state)}">${fmt(row.severity_score,1)}</span>`;if(k==='aPrice')return fmt(row.a_close,3);if(k==='hPrice')return fmt(row.h_close,3);if(k==='comp')return fmt(row.comparability_score,0,'/100');if(k==='z')return fmt(row.change_z,2);if(k==='industry')return esc(row.industry||'—');if(k==='liveAge')return age(row.live_age_seconds);return '—'}
function companyCell(r,star=true){return `<div class="company-cell">${star?`<button class="watch-star" data-star="${esc(r.company_id)}">${st.watchlist.includes(r.company_id)?'★':'☆'}</button>`:''}<div class="name-stack"><b>${esc(r.company_name)}</b><small>${esc(r.a_ticker)} / ${esc(r.h_ticker)}</small></div></div>`}
function renderScreen(){renderFilters();renderScreenTable();$('#screenResultCount').textContent=`${st.screenCount} 个结果`;$('#screenSortLabel').textContent=`排序：${sortLabel(st.sort.by)} ${st.sort.dir==='desc'?'↓':'↑'}`;$('#screenUpdatedAt').textContent='更新 '+time(new Date())}
function renderScreenTable(){let c=st.visibleCols;$('#screenerTable').innerHTML=`<thead><tr><th class="text-left"><input id="selectAllRows" type="checkbox"></th>${c.map(k=>`<th class="${META[k]?.[1]==='left'?'text-left':''}" data-sort="${k}">${esc(META[k]?.[0]||k)}</th>`).join('')}</tr></thead><tbody>${st.screenRows.map(r=>`<tr data-company="${esc(r.company_id)}" class="${st.selected.has(r.company_id)?'selected':''}"><td class="text-left"><input class="row-check" data-check="${esc(r.company_id)}" type="checkbox" ${st.selected.has(r.company_id)?'checked':''}></td>${c.map(k=>`<td class="${META[k]?.[1]==='left'?'text-left':''}">${k==='company'?companyCell(r):col(r,k)}</td>`).join('')}</tr>`).join('')}</tbody>`;bindTable($('#screenerTable'),true);let a=$('#selectAllRows');if(a)a.onchange=()=>{st.selected=a.checked?new Set(st.screenRows.map(r=>r.company_id)):new Set();renderScreenTable();bulkBar()};bulkBar()}
function bindTable(t,checks=false){$$('[data-company]',t).forEach(x=>x.onclick=e=>{if(e.target.closest('button,input'))return;selectCompany(x.dataset.company,true)});$$('[data-star]',t).forEach(b=>b.onclick=async e=>{e.stopPropagation();await toggleWatch(b.dataset.star)});if(checks)$$('[data-check]',t).forEach(c=>c.onchange=e=>{e.stopPropagation();c.checked?st.selected.add(c.dataset.check):st.selected.delete(c.dataset.check);bulkBar()});$$('[data-sort]',t).forEach(h=>h.onclick=()=>sortColumn(h.dataset.sort))}
function sortColumn(c){let k={premium:'display_premium_pct',change:'display_change_pp',percentile:'premium_percentile',residual:'company_residual_pp',priority:'severity_score',comp:'comparability_score',z:'change_z'}[c];if(!k)return;if(st.sort.by===k)st.sort.dir=st.sort.dir==='desc'?'asc':'desc';else{st.sort.by=k;st.sort.dir='desc'}loadScreen()}
function sortLabel(k){return{severity_score:'研究优先级',display_premium_pct:'A/H溢价',display_change_pp:'当日变化',premium_percentile:'历史分位',company_residual_pp:'剩余异常',comparability_score:'可比性'}[k]||k}
function renderPriority(){let cols=(st.priorityCols&&st.priorityCols.length)?st.priorityCols:PRESETS[st.preset].cols;let preset=PRESETS.find(x=>x.cols.length===cols.length&&x.cols.every((v,i)=>v===cols[i]));$('#priorityViewButton').textContent=preset?preset.label:'自定义字段';let rows=st.screenRows.filter(r=>r.quality_state==='可分析').slice(0,12);$('#priorityTable').innerHTML=`<thead><tr>${cols.map(k=>`<th class="${META[k]?.[1]==='left'?'text-left':''}" data-sort="${k}">${esc(META[k]?.[0]||k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr data-company="${esc(r.company_id)}">${cols.map(k=>`<td class="${META[k]?.[1]==='left'?'text-left':''}">${k==='company'?companyCell(r):col(r,k)}</td>`).join('')}</tr>`).join('')}</tbody>`;bindTable($('#priorityTable'))}

async function loadWatch(){try{let d=await api('/api/watchlist');st.watchlist=d.company_ids||[];st.watchRows=d.rows||[];st.watchMode=d.mode||'custom';st.watchBasis=d.selection_basis||'';let wb=$('#watchlistBasis');if(wb)wb.textContent=st.watchMode==='auto_top5'?(st.watchBasis||'默认按研究优先级 Top 5 自动生成，可手动调整'):'用户自定义自选';renderDashWatch();renderWatchPage();stars()}catch(e){toast('自选读取失败',e.message)}}
function setWatchView(v){if(!WATCH[v])return;st.watchView=v;$$('[data-watch-view]').forEach(b=>b.classList.toggle('active',b.dataset.watchView===v));$('#watchlistViewButton').textContent=WATCH[v].label;renderDashWatch();renderWatchPage()}
function renderDashWatch(){$('#watchlistCount').textContent=st.watchMode==='auto_top5'?`${st.watchRows.length} 家 · 自动Top5`:`${st.watchRows.length} 家公司`;if(!st.watchRows.length){$('#dashboardWatchlist').innerHTML=empty('尚未添加自选公司');return}$('#dashboardWatchlist').innerHTML=st.watchRows.map(r=>{let a,b;if(st.watchView==='quality'){a=`<span class="pill ${qclass(r.quality_state)}">${esc(r.quality_state)}</span>`;b=fmt(r.comparability_score,0,'/100')}else if(st.watchView==='intraday'){a=age(r.live_age_seconds);b=`<span class="pill ${rclass(r.research_state)}">${esc(r.research_state)}</span>`}else if(st.watchView==='premium'){a=fmt(r.display_premium_pct,1,'%');b=signed(r.display_change_pp,2,'pp')}else{a=fmt(r.display_premium_pct,1,'%');b=fmt(r.severity_score,0)}return `<div class="watch-row ${r.company_id===st.focusId?'active':''}" data-company="${esc(r.company_id)}"><button class="watch-star" data-star="${esc(r.company_id)}">★</button><div class="watch-company"><b>${esc(r.company_name)}</b><small>${esc(r.a_ticker)} / ${esc(r.h_ticker)}</small></div><div class="watch-num">${a}</div><div class="watch-num ${vclass(r.display_change_pp)}">${b}</div></div>`}).join('');bindTable($('#dashboardWatchlist'))}
function watchCols(){if(st.watchView==='premium')return['company','aPrice','hPrice','premium','change','percentile'];if(st.watchView==='quality')return['company','quality','comp','liveAge','priority'];if(st.watchView==='intraday')return['company','premium','change','liveAge','priority'];return['company','premium','change','driver','residual','priority']}
function renderWatchPage(){let rows=st.watchRows,q=$('#watchlistSearch')?.value.trim().toLowerCase()||'';if(q)rows=rows.filter(r=>`${r.company_name} ${r.a_ticker} ${r.h_ticker}`.toLowerCase().includes(q));let c=watchCols();$('#watchlistTable').innerHTML=`<thead><tr>${c.map(k=>`<th class="${META[k]?.[1]==='left'?'text-left':''}">${esc(META[k]?.[0]||k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr data-company="${esc(r.company_id)}">${c.map(k=>`<td class="${META[k]?.[1]==='left'?'text-left':''}">${k==='company'?companyCell(r):col(r,k)}</td>`).join('')}</tr>`).join('')}</tbody>`;bindTable($('#watchlistTable'));renderCustomWatchViews()}
async function toggleWatch(id,force){let s=new Set(st.watchlist),add=force!==undefined?force:!s.has(id);add?s.add(id):s.delete(id);await api('/api/watchlist',{method:'POST',body:JSON.stringify({company_ids:[...s]})});await loadWatch();toast(add?'已加入自选':'已移出自选',nameOf(id))} function toggleFocusWatch(){if(st.focusId)toggleWatch(st.focusId)} function nameOf(id){return(st.screenRows.find(x=>x.company_id===id)||st.watchRows.find(x=>x.company_id===id)||{}).company_name||id}

async function selectCompany(id,open=false){if(!id)return;st.focusId=id;write(STORE.focus,id);if(open)setPage('company');ensureLiveSocket();await loadFocus(true)}
async function loadFocus(withHist=true){if(!st.focusId)return;try{st.focus=await api('/api/company/'+encodeURIComponent(st.focusId));renderFocus();if(withHist){await loadHistory();st.focus=await api('/api/company/'+encodeURIComponent(st.focusId));renderFocus();await loadAnalogs()}stars()}catch(e){toast('公司研究加载失败',e.message)}}
function renderFocus(){let r=st.focus||{};let meta=r.company_name?`${r.a_ticker} / ${r.h_ticker} · ${r.industry||'—'}`:'—';$('#focusCompanyName').textContent=r.company_name||'选择公司';$('#focusCompanyMeta').textContent=meta;$('#focusPremium').textContent=fmt(r.display_premium_pct??r.a_premium_pct,1,'%');$('#focusChange').textContent=signed(r.display_change_pp??r.premium_change_pp,2,'pp');$('#focusChange').className=vclass(r.display_change_pp??r.premium_change_pp);$('#focusPercentile').textContent=pct(r.premium_percentile);$('#focusResearchState').textContent=r.research_state||'—';$('#insightHeadline').textContent=r.headline||'—';$('#insightNarrative').textContent=r.narrative||'—';contrib('#contributionList',r);checks('#qualityChecks',r.checks||[]);$('#companyName').textContent=r.company_name||'选择公司';$('#companyMeta').textContent=meta;$('#companyHeadline').textContent=r.headline||'—';$('#companyNarrative').textContent=r.narrative||'—';contrib('#companyContribution',r);checks('#companyChecks',r.checks||[]);companyKpis(r);companyQuality(r);alertBtn()}
function contrib(sel,r){let a=[['A股价格贡献',r.a_contribution_pp],['H股价格贡献',r.h_contribution_pp],['汇率贡献',r.fx_contribution_pp],['行业共同变化',r.industry_common_change_pp],['公司级剩余',r.company_residual_pp]];$(sel).innerHTML=a.map(([l,v])=>`<div class="contribution-row"><span>${l}</span><b class="${vclass(v)}">${signed(v,2,'pp')}</b></div>`).join('')}
function checks(sel,a){$(sel).innerHTML=a.map(x=>`<div class="check-row"><span>${esc(x.label)}</span><b class="${x.state==='pass'?'value-positive':x.state==='warn'?'value-negative':''}">${esc(x.value)}</b></div>`).join('')}
function companyKpis(r){let a=[['A/H溢价',fmt(r.display_premium_pct??r.a_premium_pct,1,'%')],['当日变化',signed(r.display_change_pp??r.premium_change_pp,2,'pp')],['历史分位',pct(r.premium_percentile)],['剩余异常',signed(r.company_residual_pp,2,'pp')],['可比性',fmt(r.comparability_score,0,'/100')],['研究优先级',fmt(r.severity_score,1)]];$('#companyKpis').innerHTML=a.map(([l,v])=>`<div><span>${l}</span><b>${v}</b></div>`).join('')}
function companyQuality(r){let a=[['跨市场可比性',fmt(r.comparability_score,0,'/100')],['展示状态',r.quality_state||'—'],['分析状态',r.analysis_status||'—'],['数据来源',r.data_source||r.live_source||'—']];$('#companyQualityGrid').innerHTML=a.map(([l,v])=>`<div class="metric-card"><span>${l}</span><b>${esc(v)}</b></div>`).join('');$('#companyQualityDetail').innerHTML=detail([['质量结论',r.quality_state||'—'],['核验原因',r.quality_reason||r.comparability_reasons||'—'],['行情时间',r.fetched_at?time(r.fetched_at):r.date||'日频'],['行情年龄',age(r.live_age_seconds)]])}
async function loadHistory(){if(!st.focusId)return;try{let d=await api(`/api/company/${encodeURIComponent(st.focusId)}/history?days=${Math.max(st.chartDays,st.companyDays)}`);st.history=d.rows||[];st.historyMeta=d||{};renderDashChart();renderCompanyOverview();renderCompanyPrice();renderHistoryTable()}catch(e){st.historyMeta={};toast('历史数据加载失败',e.message)}}
function rows(days){return st.history.slice(-days)}
function lineChart(sel,data,mode){
 let el=$(sel);if(!el)return;if(!data.length){el.innerHTML=empty('暂无历史数据');return[]}
 let w=Math.max(500,el.clientWidth||700),h=Math.max(220,el.clientHeight||300),p={l:48,r:16,t:16,b:28};
 let series=mode==='normalized'?[['A股','a_normalized','#3d4247'],['H股折算','h_normalized','#a1843a']]:mode==='volume'?[['A股成交','a_volume','#666d73'],['H股成交','h_volume','#b69a4c']]:[['A/H溢价','a_premium_pct','#353a3e'],['滚动中位','premium_rolling_median','#ad9147']];
 let vals=series.flatMap(ss=>data.map(r=>n(r[ss[1]])).filter(x=>x!=null));if(!vals.length){el.innerHTML=empty('该模式暂无数据');return[]}
 let mn=Math.min(...vals),mx=Math.max(...vals);if(mn===mx){mn--;mx++}let mm=(mx-mn)*.08;mn-=mm;mx+=mm;
 let X=i=>p.l+(w-p.l-p.r)*i/Math.max(1,data.length-1),Y=v=>p.t+(h-p.t-p.b)*(1-(v-mn)/(mx-mn));
 let grid='';for(let i=0;i<5;i++){let v=mn+(mx-mn)*i/4,y=Y(v);grid+=`<line x1="${p.l}" y1="${y}" x2="${w-p.r}" y2="${y}" stroke="#edf0f2"/><text x="${p.l-7}" y="${y+3}" text-anchor="end" font-size="10" fill="#7c8389">${chartValue(v)}</text>`}
 let paths='';series.forEach((ss,j)=>{let d='',go=false;data.forEach((r,i)=>{let v=n(r[ss[1]]);if(v==null){go=false;return}d+=`${go?'L':'M'}${X(i).toFixed(1)},${Y(v).toFixed(1)} `;go=true});paths+=`<path d="${d}" fill="none" stroke="${ss[2]}" stroke-width="1.8" ${j===1&&mode==='premium'?'stroke-dasharray="5 4"':''}/>`});
 el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}${paths}<text x="${p.l}" y="${h-7}" font-size="10" fill="#7c8389">${esc(dateOnly(data[0].date))}</text><text x="${w-p.r}" y="${h-7}" text-anchor="end" font-size="10" fill="#7c8389">${esc(dateOnly(data.at(-1).date))}</text><line class="hover-line" x1="0" y1="${p.t}" x2="0" y2="${h-p.b}" stroke="#8c9297" stroke-width="1" stroke-dasharray="3 3" visibility="hidden"/></svg><div class="chart-tooltip"></div>`;
 let tip=$('.chart-tooltip',el),cross=$('.hover-line',el);
 el.onmousemove=e=>{let rect=el.getBoundingClientRect(),rx=Math.max(0,Math.min(rect.width,e.clientX-rect.left)),plotL=p.l/w*rect.width,plotR=p.r/w*rect.width,plotW=Math.max(1,rect.width-plotL-plotR),ratio=Math.max(0,Math.min(1,(rx-plotL)/plotW)),idx=Math.round(ratio*Math.max(0,data.length-1)),row=data[idx];if(!row)return;let sx=X(idx);cross.setAttribute('x1',sx);cross.setAttribute('x2',sx);cross.setAttribute('visibility','visible');let lines=series.map(ss=>`<div><span><i style="background:${ss[2]}"></i>${esc(ss[0])}</span><b>${chartValue(row[ss[1]])}</b></div>`).join('');tip.innerHTML=`<strong>${esc(dateOnly(row.date))}</strong>${lines}`;tip.classList.add('show');let left=rx+14;if(left+190>rect.width)left=rx-204;tip.style.left=Math.max(8,left)+'px';tip.style.top='14px';if(sel==='#dashboardChart')$('#chartHoverInfo').textContent=`${dateOnly(row.date)} · ${series.map(ss=>`${ss[0]} ${chartValue(row[ss[1]])}`).join(' · ')}`};
 el.onmouseleave=()=>{tip.classList.remove('show');cross.setAttribute('visibility','hidden');if(sel==='#dashboardChart')$('#chartHoverInfo').textContent='移动鼠标查看明细'};
 return series
}
function historySourceLabel(){let m=st.historyMeta||{},src=(m.sources||[]).map(x=>x==='eastmoney'?'东方财富日线':x==='demo_full_universe'?'本地预览数据':x).join(' / ');if(m.data_mode==='offline_preview'){let expected=m.expected_through?` · 待补至 ${m.expected_through}`:'';let reason=m.sync?.status==='failed'?' · 在线同步失败':m.sync?.status==='stale'?' · 在线数据仍滞后':'';return `${src||'本地预览数据'}${expected}${reason}`}return src||'正式日线'}function renderDashChart(){let s=lineChart('#dashboardChart',rows(st.chartDays),st.chartMode)||[];$('#chartLegend').innerHTML=s.map(x=>`<span style="color:${x[2]}">${esc(x[0])}</span>`).join('');$('#chartDataSource').textContent=historySourceLabel()}function renderCompanyOverview(){lineChart('#companyOverviewChart',rows(st.companyDays),'premium');let m=st.historyMeta||{},suffix=m.to?` · 日线至 ${dateOnly(m.to)}`:'';$('#companyChartSubtitle').textContent=st.focus?`${st.focus.a_ticker} / ${st.focus.h_ticker}${suffix}`:'—'}function renderCompanyPrice(){lineChart('#companyPriceChart',rows(st.companyDays),st.companyPriceMode)}
function renderHistoryTable(){let a=rows(40).slice().reverse();$('#companyHistoryTable').innerHTML=`<thead><tr><th class="text-left">日期</th><th>A股</th><th>H股</th><th>汇率</th><th>A/H溢价</th><th>日变化</th><th>Z值</th></tr></thead><tbody>${a.map(r=>`<tr><td class="text-left">${dateOnly(r.date)}</td><td>${fmt(r.a_close,3)}</td><td>${fmt(r.h_close,3)}</td><td>${fmt(r.fx_cnh_per_hkd,4)}</td><td>${fmt(r.a_premium_pct,1,'%')}</td><td class="${vclass(r.premium_change_pp)}">${signed(r.premium_change_pp,2,'pp')}</td><td>${fmt(r.change_z,2)}</td></tr>`).join('')}</tbody>`}

async function loadAnalogs(show=false){if(!st.focusId)return;try{let d=await api('/api/company/'+encodeURIComponent(st.focusId)+'/analogs');st.analogs=d.rows||[];st.analogSummary=d.summary||{};renderAnalogs();if(show)toast('历史验证已更新',`${st.analogs.length} 个相似样本`)}catch(e){toast('历史验证失败',e.message)}}
function analog(r,...k){for(let x of k)if(r[x]!=null)return r[x];return null}function renderAnalogs(){let s=st.analogSummary||{},a=[['相似事件',s.count??st.analogs.length],['1日收敛率',s.convergence_1d==null?'—':fmt(s.convergence_1d*100,0,'%')],['5日收敛率',s.convergence_5d==null?'—':fmt(s.convergence_5d*100,0,'%')],['20日收敛率',s.convergence_20d==null?'—':fmt(s.convergence_20d*100,0,'%')]];let cards=a.map(([l,v])=>`<div class="metric-card"><span>${l}</span><b>${v}</b></div>`).join('');$('#companyAnalogSummary').innerHTML=cards;$('#historySummary').innerHTML=cards;$('#historySecurityContext').textContent=st.focus?`${st.focus.company_name} · ${st.focus.a_ticker} / ${st.focus.h_ticker} · 当前溢价 ${fmt(st.focus.display_premium_pct??st.focus.a_premium_pct,1,'%')}`:'—';let tab=`<thead><tr><th class="text-left">历史日期</th><th>当日溢价</th><th>当日变化</th><th>1日后</th><th>5日后</th><th>20日后</th><th>距离</th></tr></thead><tbody>${st.analogs.map(r=>`<tr><td class="text-left">${esc(dateOnly(r.date))}</td><td>${fmt(r.a_premium_pct,1,'%')}</td><td>${signed(r.premium_change_pp,2,'pp')}</td><td>${signed(analog(r,'premium_change_1d','forward_1d_change_pp'),2,'pp')}</td><td>${signed(analog(r,'premium_change_5d','forward_5d_change_pp'),2,'pp')}</td><td>${signed(analog(r,'premium_change_20d','forward_20d_change_pp'),2,'pp')}</td><td>${fmt(analog(r,'similarity_distance','similarity_score'),2)}</td></tr>`).join('')}</tbody>`;$('#companyAnalogsTable').innerHTML=tab;$('#historyTable').innerHTML=tab}

async function loadQuality(show=false){try{let d=await api('/api/data-quality');st.qualityRows=d.rows||[];st.qualitySummary=d.summary||{};renderQualitySummary();renderQualityTable();if(show)toast('数据质量已重新检查',`${st.qualityRows.length} 个问题样本`)}catch(e){toast('数据质量读取失败',e.message)}}
function renderQualitySummary(){let s=st.qualitySummary||{};$('#qualitySummary').innerHTML=[['全部公司',s.total],['可分析',s.analyzable],['谨慎',s.caution],['待核验',s.quarantined]].map(([l,v])=>`<div class="metric-card"><span>${l}</span><b>${v??'—'}</b></div>`).join('')}
function renderQualityTable(){let a=st.qualityRows;if(st.qualityFilter!=='all')a=a.filter(r=>r.quality_state===st.qualityFilter);if(st.qualitySearch)a=a.filter(r=>`${r.company_name} ${r.a_ticker} ${r.h_ticker}`.toLowerCase().includes(st.qualitySearch));$('#qualityTable').innerHTML=`<thead><tr><th class="text-left">公司</th><th>原始溢价</th><th>日变化</th><th>可比性</th><th class="text-left">状态</th><th class="text-left">问题原因</th><th>行情年龄</th></tr></thead><tbody>${a.map(r=>`<tr data-company="${esc(r.company_id)}"><td class="text-left">${companyCell(r,false)}</td><td>${fmt(r.a_premium_pct,1,'%')}</td><td>${signed(r.premium_change_pp,2,'pp')}</td><td>${fmt(r.comparability_score,0,'/100')}</td><td class="text-left"><span class="pill ${qclass(r.quality_state)}">${esc(r.quality_state)}</span></td><td class="text-left">${esc(r.quality_reason||'—')}</td><td>${age(r.live_age_seconds)}</td></tr>`).join('')}</tbody>`;bindTable($('#qualityTable'))}


function money(v){if(n(v)==null)return '—';let x=n(v);return Math.abs(x)>=1e8?(x/1e8).toFixed(2)+'亿':Math.abs(x)>=1e4?(x/1e4).toFixed(1)+'万':x.toFixed(0)}
function volumeShares(v){if(n(v)==null)return '—';let x=n(v),a=Math.abs(x);return a>=1e8?(x/1e8).toFixed(2)+'亿股':a>=1e4?(x/1e4).toFixed(1)+'万股':x.toFixed(0)+'股'}
function turnoverLocal(v,market){if(n(v)==null)return '—';let prefix=market==='A'?'¥':'HK$';return prefix+money(v)}
function freshClass(v){return v==='实时'?'live':v==='暂停计算'?'pause':['单边','竞价','午间','上一收盘','收盘','收盘参考','手动','延迟'].includes(v)?'delay':'stale'}
function liveLeg(r,leg){let src=String(leg==='a'?r.a_source:r.h_source||'').toLowerCase(),px=n(leg==='a'?r.a_price:r.h_price);return px!=null&&px>0&&!src.includes('pending')&&!src.includes('bootstrap')}
function premiumAvailable(r){return n(r?.premium_pct)!=null&&r?.quality_state!=='暂停计算'&&!['等待行情','本地缓存'].includes(String(r?.quality_state||''))}
function premiumModeLabel(r){let q=String(r?.quality_state||'');return q==='实时可比'?'A/H溢价（实时同步）':q==='单边指示'?'A/H溢价（单边指示）':q==='竞价指示'?'A/H溢价（竞价指示）':q==='午间快照'?'A/H溢价（午间快照）':q==='上一收盘'?'上一交易日A/H收盘溢价':q==='收盘口径'?'A/H收盘溢价':q==='单边收盘参考'?'A/H日终参考':q==='手动快照'?'A/H手动快照':'A/H溢价（A相对H）'}
function changeModeLabel(r){let q=String(r?.quality_state||'');return q==='实时可比'?'今日变化':q==='单边指示'?'今日变化（指示）':q==='竞价指示'?'今日变化（竞价）':q==='午间快照'?'上午变化（快照）':q==='收盘口径'?'收盘变化':q==='单边收盘参考'?'日终变化（参考）':'今日变化'}
function sessionLabel(v){return ({open:'实时',auction:'收盘竞价',break:'午休',closed:'已收盘',pre_open:'未开盘',holiday:'休市',reference:'手动参考'}[String(v||'')]||'参考')}
function liveVal(r,leg,key,d=3){return liveLeg(r,leg)?fmt(r[(leg==='a'?'a_':'h_')+key],d):'—'}
function liveSigned(r,leg,key,d=2,s='%'){return liveLeg(r,leg)?signed(r[(leg==='a'?'a_':'h_')+key],d,s):'—'}
async function loadMarketQuotes(show=false){
 try{
  let q=new URLSearchParams({q:st.marketSearch||'',scope:st.marketScope||'all',sort_by:st.marketSort||'premium_change',direction:'desc',limit:'500'}),d=await api('/api/market/quotes?'+q.toString());
  st.marketRows=d.rows||[];st.marketSummary=d.summary||{};st.market=d.market||st.market;st.live={...(st.live||{}),runtime:d.runtime||{},crawler:d.crawler||null,daily_crawler:d.daily_crawler||{}};
  let old=st.marketFocusId;
  if(!st.marketFocusId||!st.marketRows.some(r=>r.company_id===st.marketFocusId))st.marketFocusId=st.marketRows[0]?.company_id||null;
  st.marketFocus=st.marketRows.find(r=>r.company_id===st.marketFocusId)||st.marketFocus;
  renderMarketStatus();renderMarketTable();renderMarketFocus(false);
  if(st.marketFocusId&&(!st.marketDaily.length||old!==st.marketFocusId))await loadMarketDaily(st.marketFocusId,false);
  ensureLiveSocket();marketUi();if(show)toast('行情已刷新',time(new Date()))
 }catch(e){toast('行情读取失败',e.message)}
}
