function quoteBook(title,market,r){let a=market==='A',leg=a?'a':'h',ok=liveLeg(r,leg),px=a?r.a_price:r.h_price,pct=a?r.a_pct_change:r.h_pct_change,chg=a?r.a_change:r.h_change,open=a?r.a_open:r.h_open,high=a?r.a_high:r.h_high,low=a?r.a_low:r.h_low,prev=a?r.a_prev_close:r.h_prev_close,vol=a?r.a_volume:r.h_volume,amt=a?r.a_amount:r.h_amount,qt=a?r.a_quote_time:r.h_quote_time,session=a?r.a_session:r.h_session;let status=sessionLabel(session),statusClass=(session==='open'?'live':session==='closed'?'closed':session==='break'?'break':'ref');let updateText=ok&&qt?time(qt):'—';let vc=ok?vclass(pct):'';let stat=(label,val)=>`<div class="quote-stat"><span>${label}</span><b>${val}</b></div>`;return `<section class="quote-book"><div class="quote-book-head"><div class="quote-book-title"><b>${title}</b><small>${a?(r.a_ticker||'—'):(r.h_ticker||'—')}</small></div><span class="quote-book-status ${statusClass}">${status}</span></div><div class="quote-main"><strong class="${vc}">${ok?fmt(px,3):'—'}</strong><div class="quote-change ${vc}"><span>${ok?signed(chg,3):'—'}</span><em>${ok?signed(pct,2,'%'):'—'}</em></div></div><div class="quote-grid">${stat('今开',ok?fmt(open,3):'—')}${stat('最高',ok?fmt(high,3):'—')}${stat('最低',ok?fmt(low,3):'—')}${stat('昨收',ok?fmt(prev,3):'—')}${stat('成交量',ok?volumeShares(vol):'—')}${stat('成交额',ok?turnoverLocal(amt,market):'—')}</div><div class="quote-foot"><span>最近成交</span><b>${updateText}</b></div></section>`}
