function marketDailySeries(){let data=st.marketDaily||[],mode=st.marketDailyMode;if(mode==='a')return [{key:'a_close',label:'A股收盘',color:'#2563eb'}];if(mode==='h')return [{key:'h_close',label:'H股收盘',color:'#0f766e'}];if(mode==='premium')return [{key:'a_premium_pct',label:'A/H溢价',color:'#b7791f'}];return [{key:'a_normalized',label:'A股',color:'#2563eb'},{key:'h_normalized',label:'H股折算',color:'#0f766e'}]}
function renderMarketDailyChart(){let el=$('#marketDailyChart');if(!el)return;let data=st.marketDaily||[],meta=st.marketDailyMeta||{};let prefix=meta.range==='all'&&data.length?'全部可比历史 · ':'';let freshness=meta.expected_through&&meta.to&&dateOnly(meta.to)<dateOnly(meta.expected_through)?` · 待补至 ${dateOnly(meta.expected_through)}`:'';$('#marketDailySubtitle').textContent=data.length?`${prefix}${dateOnly(meta.from)} 至 ${dateOnly(meta.to)} · ${data.length}个交易日${freshness}`:'暂无日线';let series=marketDailySeries();$('#marketDailyLegend').innerHTML=series.map(x=>`<span><i style="background:${x.color}"></i>${x.label}</span>`).join('');if(!data.length){el.innerHTML=empty('暂无日线历史；在线历史会在启动后自动补抓');return}let w=Math.max(620,el.clientWidth||760),h=390,p={l:58,r:20,t:18,b:34};let vals=[];series.forEach(s=>data.forEach(r=>{let v=n(r[s.key]);if(v!=null)vals.push(v)}));if(!vals.length){el.innerHTML=empty('当前区间没有有效日线数值');return}let mn=Math.min(...vals),mx=Math.max(...vals);if(mn===mx){mn-=1;mx+=1}let pad=(mx-mn)*.08;mn-=pad;mx+=pad;let X=i=>p.l+(w-p.l-p.r)*i/Math.max(1,data.length-1),Y=v=>p.t+(h-p.t-p.b)*(1-(v-mn)/(mx-mn));let grid='';for(let i=0;i<5;i++){let v=mn+(mx-mn)*i/4,y=Y(v);grid+=`<line x1="${p.l}" y1="${y}" x2="${w-p.r}" y2="${y}" stroke="#edf0f2"/><text x="${p.l-8}" y="${y+4}" text-anchor="end" font-size="11" fill="#7c8389">${st.marketDailyMode==='premium'?v.toFixed(1)+'%':v.toFixed(1)}</text>`}let paths=series.map(sr=>{let d='';data.forEach((r,i)=>{let v=n(r[sr.key]);if(v==null)return;d+=`${d?'L':'M'}${X(i).toFixed(1)},${Y(v).toFixed(1)} `});return `<path d="${d}" fill="none" stroke="${sr.color}" stroke-width="2" vector-effect="non-scaling-stroke"/>`}).join('');let ticks=[0,Math.floor((data.length-1)/2),data.length-1].filter((x,i,a)=>x>=0&&a.indexOf(x)===i).map(i=>`<text x="${X(i)}" y="${h-9}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}" font-size="11" fill="#7c8389">${dateOnly(data[i].date).slice(5)}</text>`).join('');el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}${paths}${ticks}<line class="hover-line" x1="0" y1="${p.t}" x2="0" y2="${h-p.b}" stroke="#8c9297" stroke-dasharray="3 3" visibility="hidden"/></svg><div class="chart-tooltip daily-tooltip"></div>`;let tip=$('.chart-tooltip',el),cross=$('.hover-line',el);el.onmousemove=e=>{let rect=el.getBoundingClientRect(),rx=Math.max(0,Math.min(rect.width,e.clientX-rect.left)),plotLeft=(p.l/w)*rect.width,plotRight=(p.r/w)*rect.width,plotWidth=Math.max(1,rect.width-plotLeft-plotRight),ratio=Math.max(0,Math.min(1,(rx-plotLeft)/plotWidth)),idx=Math.round(ratio*Math.max(0,data.length-1)),r=data[idx];if(!r)return;let sx=X(idx);cross.setAttribute('x1',sx);cross.setAttribute('x2',sx);cross.setAttribute('visibility','visible');tip.innerHTML=`<strong>${dateOnly(r.date)}</strong><div><span>A股收盘</span><b>${fmt(r.a_close,3)}</b></div><div><span>H股收盘</span><b>${fmt(r.h_close,3)}</b></div><div><span>H股折算</span><b>${fmt(r.h_price_cny,3)}</b></div><div><span>A/H溢价</span><b>${fmt(r.a_premium_pct,2,'%')}</b></div><div><span>A股成交额</span><b>${turnoverLocal(r.a_amount,'A')}</b></div><div><span>H股成交额</span><b>${turnoverLocal(r.h_amount,'H')}</b></div>`;tip.classList.add('show');let left=rx+14;if(left+205>rect.width)left=rx-215;tip.style.left=Math.max(8,left)+'px';tip.style.top='12px';$('#marketDailyHover').textContent=`${dateOnly(r.date)} · A ${fmt(r.a_close,3)} · H ${fmt(r.h_close,3)} · 溢价 ${fmt(r.a_premium_pct,2,'%')}`};el.onmouseleave=()=>{tip.classList.remove('show');cross.setAttribute('visibility','hidden');$('#marketDailyHover').textContent='移动鼠标查看日线明细'}}
