function openSave(type){$('#saveViewType').value=type;$('#saveViewTitle').textContent=type==='screen'?'保存扫描视图':'另存自选视图';$('#saveViewName').value='';modal('#saveViewModal');setTimeout(()=>$('#saveViewName').focus(),0)}function saveView(){let type=$('#saveViewType').value,name=$('#saveViewName').value.trim();if(!name){toast('请输入视图名称');return}let id='v_'+Date.now().toString(36);if(type==='screen'){st.screens[id]={name,filters:{...st.filters},sort:{...st.sort},columns:[...st.visibleCols]};write(STORE.screens,st.screens);renderSavedScreens();$('#screenSelect').value=id;toast('扫描视图已保存',name)}else{st.watchViews[id]={name,base:st.watchView};write(STORE.watchViews,st.watchViews);renderCustomWatchViews();toast('自选视图已保存',name)}modal('#saveViewModal',false)}
