function exportCsv(){let c=st.visibleCols,head=c.map(k=>META[k][0]),rows=st.screenRows.map(r=>c.map(k=>k==='company'?r.company_name:k==='premium'?r.display_premium_pct:k==='change'?r.display_change_pp:k==='percentile'?r.premium_percentile:k==='driver'?r.driver_label:k==='residual'?r.company_residual_pp:k==='quality'?r.quality_state:k==='priority'?r.severity_score:k==='aPrice'?r.a_close:k==='hPrice'?r.h_close:k==='comp'?r.comparability_score:k==='z'?r.change_z:k==='industry'?r.industry:k==='liveAge'?r.live_age_seconds:''));let csv=[head,...rows].map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='AH_screener.csv';a.click();URL.revokeObjectURL(url);toast('已导出当前扫描结果',`${rows.length} 行`)}function bulkBar(){let k=st.selected.size;$('#bulkCount').textContent=`已选择 ${k} 项`;$('#bulkBar').classList.toggle('open',k>0)}async function bulkWatch(){let s=new Set([...st.watchlist,...st.selected]);await api('/api/watchlist',{method:'POST',body:JSON.stringify({company_ids:[...s]})});await loadWatch();toast('已加入自选',`${st.selected.size} 家公司`)}
function openSearch(){$('#searchOverlay').classList.add('open');$('#commandInput').value='';$('#commandResults').innerHTML=empty('输入公司名或代码开始搜索');setTimeout(()=>$('#commandInput').focus(),0)}async function searchTo(q,target,add=false,overlay=false){q=q.trim();if(!q){$(target).innerHTML=empty('输入公司名或代码');return}try{let d=await api('/api/companies/search?q='+encodeURIComponent(q)+'&limit=30');$(target).innerHTML=d.rows.length?d.rows.map(r=>`<button class="search-result" data-result="${esc(r.company_id)}"><div><b>${esc(r.company_name)}</b><small>${esc(r.a_ticker)} / ${esc(r.h_ticker)} · ${esc(r.industry||'—')}</small></div><span>${add?(st.watchlist.includes(r.company_id)?'已在自选':'加入自选'):esc(r.research_state||'')}</span></button>`).join(''):empty('没有匹配结果');$$('[data-result]',$(target)).forEach(b=>b.onclick=async()=>{let id=b.dataset.result;if(add){modal('#addWatchModal',false);await toggleWatch(id,true)}else{modal('#selectCompanyModal',false);if(overlay)$('#searchOverlay').classList.remove('open');let stayOnHistory=target==='#selectCompanyResults'&&st.page==='history';await selectCompany(id,!stayOnHistory);if(stayOnHistory)await loadAnalogs(true)}})}catch(e){$(target).innerHTML=empty('搜索失败：'+e.message)}}function openAddWatch(){$('#addWatchSearch').value='';$('#addWatchResults').innerHTML=empty('输入公司名或代码');modal('#addWatchModal');setTimeout(()=>$('#addWatchSearch').focus(),0)}function openSelectCompany(){$('#selectCompanySearch').value='';$('#selectCompanyResults').innerHTML=empty('输入公司名或代码');modal('#selectCompanyModal');setTimeout(()=>$('#selectCompanySearch').focus(),0)}
