 let payload={enabled:$('#customRefreshToggle').checked,watchlist_seconds:+$('#refreshWatchSeconds').value||5,priority_seconds:+$('#refreshPrioritySeconds').value||15,universe_seconds:+$('#refreshUniverseSeconds').value||60,status_seconds:+$('#refreshStatusSeconds').value||30};
