function updateDataMode(payload){let mode=(payload&&payload.data_mode)||(payload&&payload.update_log&&payload.update_log.data_mode)||((payload&&payload.online>0)?'mixed':'local_cache'),b=$('#dataModeBadge');if(!b)return;let dailyOnly=mode==='daily_online';b.className='data-mode-badge '+(mode==='online'?'online':(mode==='mixed'||dailyOnly)?'mixed':'cache');b.textContent=mode==='online'?'实时 + 在线历史':mode==='mixed'?'实时行情 + 本地历史':dailyOnly?'在线历史 · 实时待连接':'本地缓存';b.title=mode==='online'?'当前页面已接入实时行情和在线日线数据':mode==='mixed'?'实时行情已接入；历史日线仍在后台更新或使用本地样本':dailyOnly?'在线日线已更新，实时行情尚未收到成功快照':'尚未收到在线行情；页面不会把本地缓存标记成实时数据'}
function marketUi(){let m=st.market||{},on=!!m.any_open;$('#sideMarket').textContent=m.label||'市场状态未知';$('#sideRefresh').textContent=st.settings.autoRefresh===false?'自动刷新已关闭':on?`自选 ${m.watchlist_seconds||'—'}s · 全量 ${m.universe_seconds||'—'}s`:'非交易时段停止高频刷新';$$('#sideStatus .status-dot,#autoRefreshButton .status-dot').forEach(d=>d.className='status-dot '+(st.settings.autoRefresh!==false&&on?'live':'neutral'));$('#autoRefreshText').textContent=st.settings.autoRefresh===false?'自动刷新：关':on?`自动刷新 ${m.watchlist_seconds}s / ${m.priority_seconds}s / ${m.universe_seconds}s`:'自动刷新 · 等待开市';policy()}
function openAlert(){if(!st.focusId){openSearch();return}st.alerts=read(STORE.alerts,{});let a=st.alerts[st.focusId]||{metric:'change',threshold:2};$('#alertCompanyLabel').textContent=`${st.focus.company_name} · ${st.focus.a_ticker} / ${st.focus.h_ticker}`;$('#alertMetric').value=a.metric;$('#alertThreshold').value=a.threshold;$('#removeAlertButton').disabled=!st.alerts[st.focusId];modal('#alertModal')}function saveAlert(){st.alerts[st.focusId]={metric:$('#alertMetric').value,threshold:+$('#alertThreshold').value||0,enabled:true};write(STORE.alerts,st.alerts);modal('#alertModal',false);alertBtn();renderNotifications();toast('提醒已保存',st.focus.company_name)}function removeAlert(){delete st.alerts[st.focusId];write(STORE.alerts,st.alerts);modal('#alertModal',false);alertBtn();renderNotifications();toast('提醒已删除')}function alertBtn(){if($('#companyAlertButton'))$('#companyAlertButton').textContent=st.alerts[st.focusId]?'提醒已设置':'创建提醒'}
function renderNotifications(){let hi=st.screenRows.filter(r=>r.research_state==='重点关注').slice(0,12),custom=Object.entries(st.alerts).map(([id,a])=>{let r=st.screenRows.find(x=>x.company_id===id)||st.watchRows.find(x=>x.company_id===id);if(!r)return null;let val=a.metric==='change'?Math.abs(n(r.display_change_pp)||0):a.metric==='premium'?Math.abs(n(r.display_premium_pct)||0):n(r.severity_score)||0;return val>=a.threshold?{...r,note:`自定义提醒触发：${a.metric} ≥ ${a.threshold}`} : null}).filter(Boolean),all=[...custom,...hi].filter((r,i,a)=>a.findIndex(x=>x.company_id===r.company_id)===i);$('#notificationBadge').textContent=all.length;$('#notificationBadge').style.display=all.length?'grid':'none';$('#notificationList').innerHTML=all.length?all.map(r=>`<div class="notification-item" data-notify="${esc(r.company_id)}"><b>${esc(r.company_name)} · ${esc(r.research_state)}</b><p>${esc(r.note||`溢价 ${fmt(r.display_premium_pct,1,'%')}，变化 ${signed(r.display_change_pp,2,'pp')}`)}</p></div>`).join(''):empty('当前没有需要处理的通知');$$('[data-notify]').forEach(x=>x.onclick=()=>{drawer('#notificationDrawer',false);selectCompany(x.dataset.notify,true)})}
async function downloadReport(){if(!st.focusId){openSearch();return}try{let r=await fetch('/api/company/'+encodeURIComponent(st.focusId)+'/report');if(!r.ok)throw new Error(`${r.status} ${await r.text()}`);let blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${st.focus?.company_name||'AH_company'}_AH_research_card.md`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);toast('研究卡已导出',st.focus?.company_name||'')}catch(e){toast('研究卡导出失败',e.message)}}function stars(){let on=st.focusId&&st.watchlist.includes(st.focusId);['#focusStarButton','#companyStarButton'].forEach(s=>{let b=$(s);if(b){b.textContent=on?'★':'☆';b.classList.toggle('active',on)}})}function applyLayout(x,save=true){st.layout=x;$('#dashboardGrid').classList.remove('layout-chart','layout-table');if(x==='chart')$('#dashboardGrid').classList.add('layout-chart');if(x==='table')$('#dashboardGrid').classList.add('layout-table');if(save)write(STORE.layout,x)}
async function refreshPage(manual=false){if(st.page==='dashboard')await Promise.all([loadSummary(),loadWatch(),loadScreen(),loadFocus(true)]);else if(st.page==='market')await loadMarketQuotes();else if(st.page==='screener')await loadScreen();else if(st.page==='watchlist')await loadWatch();else if(st.page==='company')await loadFocus(true);else if(st.page==='history')await loadAnalogs();else if(st.page==='quality')await loadQuality();else if(st.page==='sources')await loadSources();if(manual)toast('页面已刷新',time(new Date()))}
async function autoTick(){let now=Date.now();if(now-st.clock.status>=((st.market?.status_seconds||30)*1000)){st.clock.status=now;try{let l=await api('/api/live/status');st.live=l;st.market=l.market||st.market;updateDataMode(l);marketUi();if(st.page==='sources')renderSources();if(st.page==='market')renderMarketStatus()}catch{}}if(st.settings.autoRefresh===false||!st.market?.any_open)return;let f=(st.market.watchlist_seconds||10)*1000,p=(st.market.priority_seconds||20)*1000,u=(st.market.universe_seconds||60)*1000;if(now-st.clock.fast>=f){st.clock.fast=now;if(['dashboard','company','watchlist','history'].includes(st.page)){await loadWatch();if(st.focusId&&!(liveSocketConnected&&liveSocketCompany===String(st.focusId)))await loadFocus(false)}if(st.page==='market'&&st.marketFocusId&&!(liveSocketConnected&&liveSocketCompany===String(st.marketFocusId))){await loadMarketQuotes();renderMarketFocus(false)}}if(now-st.clock.priority>=p){st.clock.priority=now;if(['dashboard','screener'].includes(st.page))await loadScreen();if(st.page==='market'&&st.marketScope!=='all')await loadMarketQuotes()}if(now-st.clock.universe>=u){st.clock.universe=now;await loadSummary();if(st.page==='quality')await loadQuality();if(st.page==='market')await loadMarketQuotes()}}

init().catch(e=>{console.error(e);toast('终端启动失败',e.message)});
